  "offsite.prune.title": "5 · Prune off-site",
  "offsite.prune.info": "Langkah ini hanya melaporkan apa yang terjadi, tidak mengatur apa pun. Apakah salinan ini di-prune ditentukan oleh append-only pada langkah 4 dan oleh nilai penyimpanan di Pengaturan, Retensi. Untuk tetap mem-prune salinan append-only, jalankan restic forget --prune di sisi penyimpanan, entah dengan jadwalnya sendiri atau dengan menyalakan sebentar server REST kedua tanpa append-only, mem-prune lewat server itu, lalu mematikannya lagi.",
  "offsite.prune.stateFarSide": "Dari sini tidak ada yang mem-prune salinan ini. Append-only aktif, jadi BombVault hanya menambah ke sana, dan prune adalah tugas sisi penyimpanan.",
