  // Off-site (rclone)
  "rclone.title": "Off-site (rclone)",
  "rclone.hint": "Tempel konfigurasi rclone untuk mencadangkan ke cloud (Backblaze B2, S3, Google Drive, …). Disimpan terenkripsi. SMB/NFS tidak memerlukan rclone: mount share di Unraid dan atur Jalur Pencadangan ke sana.",
  "rclone.configured": "Remote yang dikonfigurasi",
  "rclone.pathHint": "Lalu atur Jalur Pencadangan ke \"rclone:<remote>:<bucket>/jalur\" untuk mengirim domain itu off-site.",
  "cloud.title": "Kredensial cloud bersama (S3 / restic REST)",
  "cloud.hint": "Kredensial untuk backend restic off-site, tanpa rclone. Setelah menyimpan, atur Jalur Pencadangan ke repositori remote, mis. s3:s3.amazonaws.com/bucket/jalur, rest:http://host:8000/repo, atau sftp:user@host:/repo. Rahasia disimpan terenkripsi dan tidak pernah ditampilkan lagi.",
  "cloud.secretSet": "tersimpan, biarkan kosong untuk mempertahankan",
  "cloud.storageClass.label": "Kelas penyimpanan off-site",
  "cloud.storageClass.default": "(bawaan penyedia)",
  "cloud.storageClass.hint": "Hanya berlaku untuk backend S3 asli (repositori yang dimulai dengan s3:). Tingkatan arsip dalam (Glacier Flexible Retrieval, Deep Archive) sengaja tidak ditawarkan karena merusak pemulihan restic.",
  "cloud.credSets.title": "Set kredensial tambahan",
  "cloud.credSets.hint": "Berikan satu atau lebih target off-site kredensial S3 atau restic REST mereka sendiri, alih-alih membagikan yang di atas.",
