  "notify.appriseHint": "Arahkan ke endpoint /notify/<key> container Apprise API Anda untuk menyebar ke lebih dari 100 layanannya (Telegram, Pushover, Signal, …). Tag mengarahkan ke subset target kunci itu; biarkan kosong untuk semua.",
  "notify.matrix": "Matrix",
  "notify.matrixHomeserver": "URL homeserver",
  "notify.matrixToken": "Token akses",
  "notify.matrixRoom": "ID ruang",
  "notify.healthchecksTitle": "Healthchecks",
  "notify.healthchecks": "URL ping Healthchecks.io",
  "notify.healthchecksLifecycle": "Healthchecks di-ping selama seluruh siklus hidup pencadangan (mulai, berhasil, dan gagal) kapan pun URL diatur, terlepas dari pengaturan 'beri notifikasi saat' di atas, sehingga pemeriksaan tetap hijau saat berhasil bahkan dengan notifikasi hanya-gagal.",
  "notify.hcPerDomain": "Pemeriksaan per domain (lanjutan)",
  "notify.hcPerDomainHint": "Biarkan bidang kosong untuk menggunakan URL global di atas. Domain dengan URL-nya sendiri mendapatkan pemeriksaannya sendiri, dengan waktu berjalan dan riwayatnya sendiri.",
  "notify.scheduledSummary": "Ringkas eksekusi terjadwal",
  "notify.scheduledSummaryHint": "Kirim SATU ringkasan untuk setiap eksekusi pencadangan terjadwal (mis. \"42 dari 45 berhasil\") alih-alih pesan terpisah untuk setiap container/VM. Healthchecks sudah diringkas. Pencadangan manual tetap memberi notifikasi per item.",
  "notify.notifyOnUpdate": "Beri notifikasi saat pembaruan container",
  "notify.notifyOnUpdateHint": "Saat \"perbarui setelah pencadangan\" menaikkan container ke image yang lebih baru, kirim pesan agar Anda dapat memverifikasi bahwa ia masih berfungsi. Terpicu untuk setiap container yang diperbarui (pembaruan jarang terjadi).",
  "notify.unraid": "Notifikasi Unraid",
  "notify.unraidHint": "Mengirim ke sistem notifikasi Unraid sendiri (yang dapat meneruskan ke Pushover, email, Discord, …). Berjalan melalui koneksi SSH dari Pengaturan, Integrasi, SSH host, jadi kunci harus diotorisasi di sana, tetapi libvirt/VM TIDAK diperlukan (abaikan hasil \"libvirt not reachable\" jika Anda tidak mencadangkan VM). Gunakan Kirim tes di bawah untuk memeriksa.",
  "notify.unraidPlatformMismatch": "BombVault mendeteksi host ini sebagai \"{platform}\", bukan Unraid. Notifikasi Unraid tetap mati bahkan dengan tombol ini dinyalakan. Jika ini MEMANG host Unraid, periksa apakah /boot host telah di-bind-mount ke /host/boot di dalam container (lihat template Unraid BombVault) dan mulai ulang container.",
