  "dbdump.importRefused.version": "Server menjalankan versi {server}, dump berasal dari {dump}. Pakai image dengan versi {dump} atau lebih baru untuk impor ini.",
  "dbdump.importRefused.versionSameMajor": "Server menjalankan versi {server}, dump berasal dari {dump}. MySQL dan MariaDB hanya mengimpor dump ke versi mayor asalnya, jadi pakai image dengan versi {dump} untuk impor ini.",
