  "recovery.configManualRestart": "Pengaturan Anda sudah disiapkan. Mulai ulang container BombVault di Unraid, lalu lanjutkan. Pengaturan diterapkan pada boot berikutnya.",
  "recovery.configReloadWhenBack": "BombVault membutuhkan waktu lebih lama dari yang diharapkan untuk kembali. Muat ulang halaman ini setelah aktif kembali untuk memuat pengaturan yang telah dipulihkan.",
