  "recovery.foreignTitle": "Pulihkan dari repositori BombVault lain",
  "recovery.abTitle": "Impor dari plugin Appdata.Backup",
  "recovery.abIntro": "Mengubah arsip yang ditulis plugin Appdata.Backup menjadi titik pemulihan kontainer yang cocok, masing-masing bertanggal saat plugin membuatnya. Arsip hanya dibaca, tidak pernah diubah atau dihapus. Setiap arsip dibongkar di samping repositori, dicadangkan, lalu salinan yang dibongkar dihapus lagi, jadi di sana perlu ruang untuk arsip terbesar.",
